    ],
    "dialogue": {
      "交谈1": [
        "	罗德岛干员，煌，向你报道。拿着，这是可以直接调遣我的权限认可书，凯尔希医生已经签了名了。好了博士，就让其他小队看看我们的本事吧！"
      ],
      "交谈2": [
        "啊，博士，毛巾递我一下。嗯，今天的训练任务已经完成了。保证每天六小时的训练，才能一直处在备战状态，接到命令就立即出发。行啦，让你久等了，这次我们去哪？说好了，这回你出钱哦？"
      ],
      "交谈3": [
        "博士，你知道所有作战记录我都复盘过，不用拉着我一起看吧。等等，这个不是——不要！不要反覆看我的尾巴着火的样子！那只是一开始不熟练！"
      ],
      "晋升后交谈1": [
        "阿米娅是我见过最有天分的战士之一。她对局势的判断特别清晰，她的法术我光是看着都感到害怕。只不过仔细想想，她是怎么在这个年龄是怎么获得这种实力的？真的。我宁可她没有这样的实力。"
      ],
      "晋升后交谈2": [
        "如果需要我帮忙，别客气，开口直说！你信任我，我相信你，你指挥，我战斗，成了！现在的我们，就是罗德岛最佳拍档！啊，这些话，可别告诉阿米娅哦。"
      ]
    },
    "likes": [
      "保护感染者",
      "严苛训练和自我突破"
    ],
    "dislikes": [
      "社会对感染者的漠视与不公",
      "训练松懈和命令迟缓"
    ],
    "behavior_logic": {
      "害怕时": [
        "保持冷静，评估威胁并寻找反击机会"
      ],
      "生气时": [
        "直接表达不满，可能会采取行动"
      ],
      "开心时": [
        "以行动表达喜悦"
      ],
      "悲伤时": [
        "独自复盘，不愿打扰他人"
      ],
      "喜欢时": [
        "会以实际行动表达，如赠送礼物"
      ]
    },
    "moral": [
      "为感染者而战，将保护弱者视为己任"
    ],
    "overview": [
      "龙门维多利亚出身，七年战斗经验，现任罗德岛精英近卫干员。"
    ],
    "background": [
      "出生于维多利亚贵族家庭，后因源石病被逐出并目睹不公；加入罗德岛后，以链锯术和战术机动著称。"
    ],
    "人际关系": {
      "阿米娅": "指挥官、同袍",
      "灰喉": "并肩作战伙伴",
      "凯尔希": "签署调遣授权医生",
      "史尔特尔": "训练同伴"
    }
